// strings.page.js — PAGE-CHROME UI copy shard (the "make the whole page dynamic"
// migration). Holds every previously-INLINE user-visible string that used to be
// hard-coded in the React components (header, map-shell sheets, ux toasts/tutorial,
// the report form/filters, the home InfoPanel + legend + acknowledgements). These
// were rendered as literal pt-BR and therefore did NOT switch on a language change;
// routing them through t('page.*') makes them re-render live via App.js's
// 'mdf-locale-change' forceUpdate, with no reload.
//
// WHY A SEPARATE SHARD (not strings.core/assinar/pets.js): those shards are owned
// by the in-flight 7-locale feature; this file is additive and isolated so the two
// efforts never collide. dictionary.js spreads this shard LAST per locale.
//
// Namespacing by surface: page.header.*, page.report.*, page.pin.*, page.list.*,
// page.context.*, page.popup.*, page.install.*, page.tutorial.*, page.steps.*,
// page.filter.*, page.form.*, page.info.*, page.legend.*, page.thanks.*.
//
// LOCALE PARITY (test/i18n.test.js): every block below MUST expose the SAME key set
// (data-driven over SUPPORTED_LOCALES = pt-BR/es/en-US/de/fr/ru/zh). pt-BR carries
// the verbatim current Portuguese (dark-ship: the default page must read byte-for-
// byte as today). MECHANICAL copy (buttons, nav, filters, plain labels) is finalized
// in every locale. DIGNITY-SENSITIVE copy (hunger/health/need consequences, the
// reassurance/consent/report prompts) is DRAFTED and prefixed `[REVISAR-HUMANO] ` in
// the non-pt locales so a human approves tone before ship (honors plan D7 — never
// machine-translate sensitive copy). New strings avoid the em-dash (commas/parens).

