  'page.partners.title':           'Sé socio de MAPA FOME',
  'page.partners.lead':            'MAPA FOME es una plataforma pública, gratuita y anónima que permite a cualquier ciudadano, en tres toques, mapear a personas en situación de inseguridad alimentaria para que voluntarios cercanos lleven ayuda en tiempo real. Las empresas socias sostienen la operación y ganan visibilidad honesta junto a comunidades activas, sin vigilar a nadie.',
