  'page.partners.tier_choose':       'Choose this tier',
  'page.partners.dignity_title':   'Dignity checklist (non-negotiable)',
  'page.partners.dignity_1':       'Banner in Portuguese, no motion loop, no vivid red competing with the report CTA.',
  'page.partners.dignity_2':       'Gambling, predatory-loan, abusive payroll-credit brands or products with a public record of labor violations are refused.',
  'page.partners.dignity_3':       'No banner appears over a mapped person\'s point. Slots only on institutional surfaces (InfoPanel, /apoiar, /iniciativas, /parceiros).',
  'page.partners.dignity_4':       'No individual tracking: we do not use a pixel, device id or retargeting cookie. The report counts aggregated points within the contracted time × space rectangle.',
  'page.partners.dignity_5':       'Co-brand opt-in: if there is joint promotion, the project approves it in writing before it goes live.',
