  'page.partners.faq_title':       'Frequently asked questions',
  'page.partners.faq1_q':          'Can I run a campaign for just one neighborhood?',
  'page.partners.faq1_a_lead':     'Yes, the ',
  'page.partners.faq1_a_tail':     ' tier accepts a 3 km radius around your business. You set the address and the duration.',
  'page.partners.faq2_q':          'How do you prove the reach of my campaign?',
  'page.partners.faq2_a_lead':     'At ',
  'page.partners.faq2_a_tail':     ', open. We show, per campaign, the potential audience (need points reported in the contracted time × space rectangle) and the engaged one (of those, how many were served by a volunteer). Exportable in JSON and CSV.',
  'page.partners.faq3_q':          'Do you track users to sell me data?',
  'page.partners.faq3_a':          'No. Never. MAPA FOME does not use a pixel, retargeting cookie or device id. Metrics are aggregated by territory and time. Companies looking for retargeting should use another channel.',
  'page.partners.faq4_q':          'Can we contribute with product instead of money?',
  'page.partners.faq4_a_lead':     'Yes, the ',
  'page.partners.faq4_a_tail':     ' tier accepts food baskets, freight, agency hours, cloud hosting, among others. It must be valued in the partnership agreement for accounting records.',
  'page.partners.faq5_q':          'Can my banner sit over a point on the map?',
  'page.partners.faq5_a':          'No. No banner appears on the map or over the mapped person. Slots live on institutional surfaces (InfoPanel footer, /apoiar, /iniciativas, /parceiros).',

