  'page.legend.yellow_label':   'In Gelb',
  'page.legend.yellow_desc':    'Menschen in sozialer Notlage und Ernährungsunsicherheit, die zu Hause oder auf der Straße hungern und Nahrung brauchen.',
  'page.legend.blue_label':     'In Blau',
  'page.legend.blue_desc':      'Menschen oder Initiativen, die Lebensmittel oder Mittel zum Verteilen in der Gemeinschaft erhalten (Suppenküche, NGOs, Freiwillige) und Spenden brauchen.',
  'page.legend.red_label':      'In Rot',
  'page.legend.red_desc':       'Menschen oder Gruppen, die an einem festen Straßenpunkt an einem bestimmten Wochentag eine Mahlzeit ausgeben, als Ausgabepunkt für fertiges Essen.',
  'page.legend.green_label':    'In Grün',
  'page.legend.green_desc':     'Menschen, die mit Lebensmitteln arbeiten und Unverkauftes weitergeben müssen (Restaurant, Hotel, Markt, Supermarkt) und Freiwillige zum Abholen brauchen.',
  'page.creators.heading':      'Mapa Fome Inhaltsersteller',
  'page.creators.iframe_title': 'Creators Mapa Fome',
  'page.thanks.a0':           '[REVISAR-HUMANO] In Dankbarkeit für die menschliche, moralische und ethische Bildung, die ich von meinen Philosophie- und Soziologielehrern in der Oberstufe erhalten habe.',
  'page.thanks.a1':           '[REVISAR-HUMANO] Nach 10 Jahren, in denen ich unsere Rolle als Gesellschaft beobachtet, gelernt und verinnerlicht habe, hatte ich die Gelegenheit, mit angesammeltem Wissen und Technologien zu handeln.',
  'page.thanks.a2':           '[REVISAR-HUMANO] Und die Grundlage zum Erstellen von Projekten (Feldforschung und Project Manager), erworben im Kurs Projetão CIn UFPE.',
  'page.thanks.a3':           '[REVISAR-HUMANO] Daraus entstanden die nötigen Werkzeuge, um zugunsten der hungernden Menschen zu handeln.',
  'page.thanks.a4':           '[REVISAR-HUMANO] Und Sichtbarkeit zu schaffen, gemeinsam mit den gutherzigen Menschen, die regelmäßig jene ernähren, die kein Geld haben, um Essen zu kaufen.',
  'page.thanks.a5':           '[REVISAR-HUMANO] Und mit den Lebensmittelhändlern dazu beizutragen, Verschwendung zu verringern.',
  'page.thanks.a6':           '[REVISAR-HUMANO] Und zu motivieren und Werkzeuge anzubieten, damit jeder Mensch seinen Teil beiträgt und regelmäßig mithilft.',
  'page.thanks.a7':           '[REVISAR-HUMANO] Oder, wenn nicht mit Essen, dann durch das Teilen von Informationen, indem man jenen, die es brauchen, und jenen, die helfen können, von MAPA FOME erzählt.',
  'page.thanks.a8':           '[REVISAR-HUMANO] Ohne Nahrung stirbt jeder Mensch vorzeitig. Unterlassene Hilfeleistung, wenn sie ohne eigene Gefahr möglich ist, stellt die Straftat der unterlassenen Hilfeleistung dar (Art. 135 des brasilianischen Strafgesetzbuchs).',
  'page.thanks.doc_lead':       '[REVISAR-HUMANO] Dafür, dass sie den preisgekrönten 13-minütigen Kurzdokumentarfilm des Brasilianers Jorge Furtado gezeigt haben,',
  'page.timeline.t0_time':    '0–3 horas',
  'page.timeline.t0_conseq':  'Minimale Veränderung.',
  'page.timeline.t1_time':    '4–8 horas',
  'page.timeline.t1_conseq':  'Mehr Hunger, leichtes Bauchweh, möglicherweise Kopfschmerzen.',
  'page.timeline.t2_time':    '9–12 horas',
  'page.timeline.t2_conseq':  'Müdigkeit, Gereiztheit, Stress und Kopfschmerzen.',
  'page.timeline.t3_time':    '13–16 horas',
  'page.timeline.t3_conseq':  'Schwierigkeiten, aufmerksam zu sein und sich zu konzentrieren.',
  'page.timeline.t4_time':    '17–24 horas',
  'page.timeline.t4_conseq':  'Zu wenig Zucker im Körper: Schwindel oder Zittern.',
  'page.timeline.t5_time':    '25–48 horas',
  'page.timeline.t5_conseq':  'Schwäche und Überlebensmodus: das Herz schlägt schneller, weil Energie fehlt.',
  'page.timeline.t6_time':    '49–72 horas',
  'page.timeline.t6_conseq':  'Der Körper greift auf gespeichertes Fett zurück; das Immunsystem wird schwächer.',
  'page.timeline.t7_time':    '3–7 dias',
  'page.timeline.t7_conseq':  'Muskeln werden als Energie verbraucht. Weniger Motivation und Produktivität.',
  'page.timeline.t8_time':    '8–14 dias',
  'page.timeline.t8_conseq':  'Die Organe beginnen zu leiden und die Person wird viel leichter krank.',
  'page.timeline.t9_time':    '15–21 dias',
  'page.timeline.t9_conseq':  'Das Leben ist in Gefahr.',
  'page.timeline.t10_time':    '22+ dias',
  'page.timeline.t10_conseq':  'Extreme Gefahr: die Organe können jederzeit aufhören zu arbeiten.',
