  'page.hungertable.conseq_0':   'Minimale Veränderung',
  'page.hungertable.conseq_1':   'Du wirst mehr Hunger spüren und dein Bauch wird ein wenig schmerzen, und du kannst Kopfschmerzen bekommen',
  'page.hungertable.conseq_2':   'Du wirst dich müde und gereizt fühlen, wütend, reizbar, gestresst und du wirst Kopfschmerzen haben',
  'page.hungertable.conseq_3':   'es wird schwerer, aufmerksam zu sein oder sich zu konzentrieren',
  'page.hungertable.conseq_4':   'Dein Körper wird nicht genug Zucker haben, wodurch du dich schwindelig oder ZITTRIG fühlst',
  'page.hungertable.conseq_5':   'Du wirst dich schwach fühlen und in eine Situation hohen Stresses und in den Überlebensmodus geraten, dein Herz wird schneller schlagen, weil die Energie aus der Nahrung fehlt, also versucht es doppelt zu arbeiten, um das Ergebnis zu halten (Sauerstoff und Nährstoffe zu den lebenswichtigen Organen zu liefern)',
  'page.hungertable.conseq_6':   'Dein Körper beginnt, gespeicherte Energie zu nutzen (Fett,...), wodurch du dich müde fühlst und dein Immunsystem nicht mehr so gut funktioniert, du wirst leichter krank',
  'page.hungertable.conseq_7':   'Die Muskeln werden als Energie verbraucht, du wirst dich sehr schwach fühlen und deine Muskeln werden schrumpfen. Das ist nicht gut für deinen Körper, es schädigt den Organismus. Geringere Motivation oder Produktivität',
  'page.hungertable.conseq_8':   'Deine Organe, die wichtige Teile deines Körpers sind, werden geschädigt und du wirst viel leichter krank',
  'page.hungertable.conseq_9':   'Du wirst sehr krank und dein Leben wird in Gefahr sein',
  'page.hungertable.conseq_10':  'Du bist in extremer Gefahr, weil dein Körper nicht genug Nahrung bekommt, und deine Organe werden aufhören, richtig zu funktionieren, oder jederzeit stehen bleiben',
