  'page.info.conclusion_label':    'Fazit:',
  'page.info.conclusion_body':     'Ich appelliere an dich, regelmäßige solidarische Maßnahmen und Handlungen zu ergreifen, in Abständen von 1 bis 14 Tagen. Lindere den Schmerz und das Leid eines anderen Menschen.',
