  'page.info.closing':             'Niemand sollte neben uns hungern. Tu heute deinen Teil: spende, setze einen Punkt auf der Karte oder teile MAPA FOME.',

  // ── route page: /parceiros ──
  'page.partners.back':            '← Karte',
  'page.partners.title':           'Werde Partner von MAPA FOME',
  'page.partners.lead':            'MAPA FOME ist eine öffentliche, kostenlose und anonyme Plattform, die es jedem Bürger ermöglicht, in drei Tipps Menschen in Ernährungsunsicherheit zu kartieren, damit Freiwillige in der Nähe in Echtzeit Hilfe bringen. Partnerunternehmen tragen den Betrieb und gewinnen ehrliche Sichtbarkeit neben aktiven Gemeinschaften, ohne jemanden zu überwachen.',
  'page.partners.how_title':       'Wie das Sponsoring funktioniert',
  'page.partners.how_step1':       'Du wählst eine Stufe (Viertel, Stadt, Bundesstaat oder national) und ein Zeitfenster.',
  'page.partners.how_step2':       'Du sendest das PNG-Banner (Bildvertrag mit 150 Zeichen + Würde-Checkliste).',
  'page.partners.how_step3':       'Wir richten die Kampagne mit geografischem Zentrum + Radius + Daten ein. Sie erscheint nur für Personen innerhalb dieses Radius.',
  'page.partners.how_step4_lead':  'Monatlich erhältst du Zugang zum ',
  'page.partners.how_step4_link':  'Marketing-Bericht',
  'page.partners.how_step4_tail':  ' mit potenziellem und engagiertem Publikum, in offenem Format.',
  'page.partners.tiers_title':     'Sponsoring-Stufen',
  'page.partners.tiers_caption':   'Richtwerte, verhandelbar. Ziel ist es, den Betrieb zu tragen: Ein Teil der Einnahmen wird zu digitalem Marketing, das mehr aktive Freiwillige bringt.',
