  // ── route page: /imprensa ──
  'page.press.back':               '← Karte',
  'page.press.title':              'MAPA-FOME-Pressekit',
  'page.press.lead':               'Diese Seite versammelt alles, was Journalisten, Content-Ersteller und Partner brauchen, um über MAPA FOME zu sprechen, ohne uns vorher zu schreiben. Lade die Logos herunter, kopiere die fertigen Beschreibungen, sieh dir das Datenblatt, die Farben und die Nutzungsregeln an, und nimm zitierfähige Sätze. Es ist kostenlos und frei für die redaktionelle Nutzung, mit Quellenangabe. Wir bitten nur um eines im Gegenzug: Respektiere die Würde derer, die kartiert werden, sie sind Bürger, die Bürger verbinden, keine Opfer und keine Wohltätigkeitsfälle. MAPA FOME ersetzt niemanden; es verbindet alle.',
  'page.press.intro_title':        'Was MAPA FOME ist',
  'page.press.icon_alt':           'MAPA-FOME-Symbol',
  'page.press.eyebrow':            'Der Vorschlag',
  'page.press.intro_body':         'MAPA FOME ist eine kollaborative, öffentliche, kostenlose und anonyme Karte. In drei Tipps markiert jeder auf der Karte jemanden in einer Hungersituation, damit Freiwillige in der Nähe in Echtzeit Hilfe bringen. Es ist freie Software, mit offenen Daten, geboren in Recife, mit Ursprung 2022 während des Informatikstudiums am CIn UFPE, und in Expansion durch Brasilien. Nicht verhandelbares Prinzip: Wir helfen Menschen, wir überwachen keine Menschen.',
  'page.press.framing':            'Vorgeschlagene Rahmung: Bürgertechnologie und Solidarität zwischen Nachbarn, nicht Wohltätigkeit oder Mitleid.',
  'page.press.slogan':             '„Eine kollaborative Karte. Offen. In Echtzeit.“',
  'page.press.subtagline':         '„Sie ersetzt niemanden. Sie verbindet alle.“',
  'page.press.quick_title':        'Das Wesentliche in 30 Sekunden',
  'page.press.refusals_title':     'Was MAPA FOME zu tun verweigert',
  'page.press.refusals_intro':     'Was wir ablehnen, definiert das Projekt ebenso wie das, was wir anbieten. Diese Linien sind nicht verhandelbar.',
  'page.press.refusals_callout':   '„Wir kartieren den Hunger, um ihn zu verkürzen, niemals um die zu überwachen, die ihn fühlen.“',
  'page.press.assets_title':       'Logos und Assets zum Herunterladen',
  'page.press.assets_note_lead':   'Formate: PNG (transparent) für schnelle Nutzung; SVG (Vektor) für Druck und jede Größe ohne Schärfeverlust. Brauchst du ein anderes Format, einen anderen Hintergrund oder eine monochrome Version? Schreibe an ',
  'page.press.license_title':      'Nutzungsbedingungen der Assets',
  'page.press.license_intro_lead': 'Du kannst die MAPA-FOME-Assets frei in journalistischen Beiträgen, Posts, Videos und Werbematerialien über das Projekt verwenden, stets mit Quellenangabe an ',
  'page.press.license_intro_tail': '.',
