  'page.partners.back':            '← Carte',
  'page.partners.title':           'Devenez partenaire de MAPA FOME',
  'page.partners.lead':            'MAPA FOME est une plateforme publique, gratuite et anonyme qui permet à tout citoyen, en trois touches, de cartographier les personnes en situation d\'insécurité alimentaire pour que des bénévoles à proximité apportent de l\'aide en temps réel. Les entreprises partenaires soutiennent l\'opération et gagnent une visibilité honnête auprès de communautés actives, sans surveiller personne.',
  'page.partners.how_title':       'Comment fonctionne le parrainage',
