  'page.thanks.a8':           '[REVISAR-HUMANO] Без еды любой человек умирает преждевременно. Неоказание помощи, когда это возможно без риска для себя, образует преступление неоказания помощи (ст. 135 Уголовного кодекса Бразилии).',
  'page.thanks.doc_lead':       '[REVISAR-HUMANO] За то, что показали отмеченный наградами 13-минутный короткометражный документальный фильм бразильца Жоржи Фуртаду,',
