  'page.partners.back':            '← Карта',
  'page.partners.title':           'Станьте партнёром MAPA FOME',
  'page.partners.lead':            'MAPA FOME — это публичная, бесплатная и анонимная платформа, которая позволяет любому гражданину в три касания отметить на карте людей в ситуации продовольственной нужды, чтобы волонтёры поблизости доставили помощь в реальном времени. Компании-партнёры поддерживают работу проекта и получают честную видимость рядом с активными сообществами, не следя ни за кем.',
  'page.partners.how_title':       'Как работает спонсорство',
