  // ── route page: /imprensa ──
  'page.press.back':               '← Карта',
  'page.press.title':              'Пресс-кит MAPA FOME',
  'page.press.lead':               'Эта страница собирает всё, что нужно журналистам, авторам контента и партнёрам, чтобы рассказать о MAPA FOME, без необходимости писать нам заранее. Скачайте логотипы, скопируйте готовые описания, посмотрите техническую справку, цвета и правила использования, и возьмите цитируемые фразы. Это бесплатно и свободно для редакционного использования, с указанием авторства. Мы просим только одного взамен: уважайте достоинство тех, кто отмечен, это граждане, соединяющие граждан, не жертвы и не случаи благотворительности. MAPA FOME никого не заменяет; он соединяет всех.',
  'page.press.intro_title':        'Что такое MAPA FOME',
  'page.press.icon_alt':           'Значок MAPA FOME',
  'page.press.eyebrow':            'Предложение',
  'page.press.intro_body':         'MAPA FOME — это совместная, публичная, бесплатная и анонимная карта. В три касания любой отмечает на карте человека в ситуации голода, чтобы волонтёры поблизости доставили помощь в реальном времени. Это свободное ПО, с открытыми данными, родившееся в Recife, с истоком в 2022 году во время обучения по информатике в CIn UFPE, и расширяющееся по Бразилии. Непреложный принцип: мы помогаем людям, мы не следим за людьми.',
  'page.press.framing':            'Предлагаемая рамка: гражданская технология и солидарность между соседями, не благотворительность и не жалость.',
